# DK VFN.  Vanløse – Frederiksberg Nord
#
let vn = path("d3.dk.vfn");

with detail = 3, railway = :first :double :nopax :removed {
    with link = "line.dk.VFN" {
        track(:station,
                vn[:van - 0.5sw, :van.yn - 1md] << 1ms << 1md
            ..  vn[:frn.yv + 1md, :frn] << 1ms << 1md
        );
    }
}

